// Import necessary hooks
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';

function Comic({ characters }) {
  const [isComicBooksModalOpen, setIsComicBooksModalOpen] = useState(false);
  const [selectedCharacter, setSelectedCharacter] = useState(null);
  const [comics, setComics] = useState([]); // State to hold comics data

  const notAvailableImage = "http://i.annihil.us/u/prod/marvel/i/mg/b/40/image_not_available.jpg";

  const handleCharacterClick = async (character) => {
    setSelectedCharacter(character);

    // Fetch comics for the selected character
    const publicKey = process.env.REACT_APP_MARVEL_PUBLIC_KEY;
    const privateKey = process.env.REACT_APP_MARVEL_PRIVATE_KEY;
    const ts = new Date().getTime();
    const hash = CryptoJS.MD5(ts + privateKey + publicKey).toString();

    try {
      const response = await axios.get(character.comics.collectionURI, {
        params: {
          apikey: publicKey,
          ts,
          hash,
        },
      });
      setComics(response.data.data.results); // Set the comics state with the fetched data
    } catch (error) {
      console.error("Error fetching comics:", error);
      setComics([]); // Reset comics state in case of error
    }

    setIsComicBooksModalOpen(true);
  };

  return (
    <div className="comic-book-content">
      {/* Existing map logic to display character cards */}
      <ComicBooksModal isOpen={isComicBooksModalOpen} comics={comics} onClose={() => setIsComicBooksModalOpen(false)}>
        {/* Modal content will be updated to display comics */}
      </ComicBooksModal>
    </div>
  );
}

export default Comic;
